import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:sandan_facility_app/contracts/work_order_acts.dart';
import 'package:sandan_facility_app/data/implemented_acts.dart';

/// SPEC-024 Phase 5, Step 0 — **guard 2**: this build is measured against the
/// act contract, and the measurement cannot be skipped.
///
/// 🔴 **Why it cannot skip.** Hashim's directive was *"لا أريد اختباراً يمكنه
/// تجاوز التحقق بصمت عند غياب التطبيق"*. The contract it reads —
/// `lib/contracts/work_order_acts.dart` — is **inside this repository**,
/// generated by `php artisan facility:acts` in the ERP and committed here. So
/// there is no sibling directory to be missing, nothing to probe for, and no
/// branch in which this file quietly passes having checked nothing.
///
/// ⚠️ **The honest boundary.** This proves the build against the contract it
/// holds. It cannot prove that contract matches the **live** server, because
/// the two repositories share no CI. That gap is covered at runtime: the ERP's
/// `lookup/vocabulary` publishes `acts`, and an act this build has no code for
/// is drawn disabled rather than enabled-and-failing.
void main() {
  test('🔴 every act the server can offer is either implemented or declared', () {
    final covered = {...implementedActs, ...notYetImplementedActs};

    // A tenth act arriving from the ERP lands here, before it ever reaches a
    // technician as a button nobody wrote code for.
    expect(
      workOrderActs.difference(covered),
      isEmpty,
      reason: 'The server offers an act this app neither implements nor declares.',
    );
  });

  test('🔴 the app claims no act the server does not have', () {
    // The other direction, and it matters just as much: an act implemented
    // here but absent from the contract is dead code that looks like a
    // feature — or a value the app would send and the server would 404.
    expect(
      {...implementedActs, ...notYetImplementedActs}.difference(workOrderActs),
      isEmpty,
    );
  });

  test('⚠️ nothing is both implemented and declared unimplemented', () {
    expect(implementedActs.intersection(notYetImplementedActs), isEmpty);
  });

  test('🎯 the dispatcher really handles exactly the acts it claims to', () async {
    // 🔴 The set above is a claim; this reads the SOURCE and checks it. Without
    // this, `implementedActs` could drift from the switch it describes and
    // every test above would still pass — which is precisely the shape of the
    // defect being fixed: a list that describes code rather than coming from
    // it.
    final source = await File('lib/screens/work_order_screen.dart').readAsString();

    final dispatcher = source.substring(
      source.indexOf('final result = switch (act.value)'),
      source.indexOf('if (!mounted) return;',
          source.indexOf('final result = switch (act.value)')),
    );

    for (final act in implementedActs) {
      // `upload_evidence` is handled before the switch — it opens the camera
      // rather than sending a transition — so the whole method body is the
      // dispatcher, not the switch alone.
      final handled = dispatcher.contains("'$act'") ||
          source.contains("act.value == '$act'");

      expect(handled, isTrue, reason: '$act is claimed as implemented but is not dispatched.');
    }

    for (final act in notYetImplementedActs) {
      expect(dispatcher.contains("'$act'"), isFalse,
          reason: '$act is dispatched but still declared unimplemented.');
    }
  });

  test('✅ the contract is the generated file, and it names all fourteen acts', () async {
    final file = await File('lib/contracts/work_order_acts.dart').readAsString();

    expect(file, contains('GENERATED by `php artisan facility:acts`'));

    // 🔧 9 → 14 with SPEC-024 Phase 5 Step 2's five manager acts. ⚠️ This
    // number is edited only after `php artisan facility:acts` has been run in
    // the ERP — the file above is GENERATED, and a count updated by hand
    // without regenerating it would pass here and lie to the dispatcher
    // check above.
    expect(workOrderActs.length, 14);

    // 🔴 And the five are the MANAGER's, named so this assertion fails for
    // the right reason if a future Step adds a sixteenth.
    expect(workOrderActs, containsAll(<String>[
      'verify', 'close', 'cancel', 'reject', 'decide_extension',
    ]));
  });
}
